"""Deutsch — Propheten (prophets_001 … prophets_150)."""

T = {
"prophets_001": ("Welcher Prophet baute auf Allahs Befehl die Arche?", ["Nuh (Noah)", "Ibrahim (Abraham)", "Musa (Mose)", "Yusuf (Josef)"], "Allah befahl Nuh, die Arche zu bauen, um die Gläubigen vor der Flut zu retten."),
"prophets_002": ("Welcher Prophet wurde in ein Feuer geworfen, das Allah für ihn kühl und sicher machte?", ["Ibrahim (Abraham)", "Nuh (Noah)", "Dawud (David)", "Ayyub (Hiob)"], "Allah befahl dem Feuer, für Ibrahim kühl und sicher zu sein."),
"prophets_003": ("Welcher Prophet wurde von einem riesigen Fisch verschluckt?", ["Yunus (Jona)", "Ilyas (Elias)", "Idris (Henoch)", "Zakariyya (Zacharias)"], "Yunus wurde vom Fisch verschluckt, nachdem er sein Volk im Zorn verlassen hatte; Allah vergab ihm."),
"prophets_004": ("Welcher Prophet deutete den Traum des Königs von sieben fetten und sieben mageren Kühen?", ["Yusuf (Josef)", "Ya'qub (Jakob)", "Isma'il (Ismael)", "Ishaq (Isaak)"], "Yusuf deutete den Traum des Königs: sieben Jahre des Überflusses, gefolgt von sieben Jahren der Hungersnot."),
"prophets_005": ("Mit welchem Propheten sprach Allah laut Koran direkt?", ["Musa (Mose)", "Harun (Aaron)", "Yusuf (Josef)", "Sulaiman (Salomo)"], "Der Koran sagt, dass Allah direkt mit Musa sprach."),
"prophets_006": ("Welcher Prophet verstand die Sprache der Vögel?", ["Sulaiman (Salomo)", "Dawud (David)", "Yunus (Jona)", "Yusuf (Josef)"], "Allah lehrte Sulaiman die Sprache der Vögel."),
"prophets_007": ("Welchem Propheten wurde die Schrift namens Zabur (Psalmen) gegeben?", ["Dawud (David)", "Musa (Mose)", "Isa (Jesus)", "Ibrahim (Abraham)"], "Der Koran erwähnt, dass der Zabur Dawud gegeben wurde."),
"prophets_008": ("Welcher Prophet wurde ohne Vater geboren, durch Allahs Wort „Sei, und es ist“?", ["Isa (Jesus)", "Yahya (Johannes)", "Isma'il (Ismael)", "Ishaq (Isaak)"], "Der Koran beschreibt Isas wunderbare Geburt ohne Vater, allein durch Allahs Wort."),
"prophets_009": ("Welches Kapitel (Sure) des Korans ist nach der Mutter eines Propheten benannt?", ["Maryam", "Yusuf", "Nuh", "Hud"], "Sure 19, Maryam, ist nach der Mutter des Propheten Isa benannt."),
"prophets_010": ("Welcher Prophet wurde mit schwerer Krankheit geprüft und wird für seine Geduld gelobt?", ["Ayyub (Hiob)", "Zakariyya (Zacharias)", "Yahya (Johannes)", "Idris (Henoch)"], "Ayyub blieb in einer sehr schweren Prüfung geduldig, und Allah belohnte ihn."),
"prophets_011": ("Vor wem befahl Allah den Engeln, sich als Zeichen der Ehre niederzuwerfen?", ["Adam", "Nuh (Noah)", "Ibrahim (Abraham)", "Musa (Mose)"], "Allah befahl den Engeln, sich vor Adam niederzuwerfen, als Zeichen der Ehre, nicht der Anbetung."),
"prophets_012": ("Welcher Prophet wird „Khalilullah“, der enge Freund Allahs, genannt?", ["Ibrahim (Abraham)", "Musa (Mose)", "Isa (Jesus)", "Muhammad ﷺ"], "Der Koran beschreibt Ibrahim als den engen Freund (Khalil) Allahs."),
"prophets_013": ("Welcher Prophet wurde von seinen Brüdern in einen Brunnen geworfen?", ["Yusuf (Josef)", "Bunyamin (Benjamin)", "Ya'qub (Jakob)", "Isma'il (Ismael)"], "Yusufs Brüder warfen ihn aus Eifersucht in einen Brunnen."),
"prophets_014": ("Wessen Volk wurde durch eine Flut vernichtet, nachdem es ihn abgelehnt hatte?", ["Nuh (Noah)", "Hud", "Salih", "Shu'ayb"], "Nuhs Volk wurde von der Flut verschlungen, nachdem es seine Botschaft beharrlich abgelehnt hatte."),
"prophets_015": ("Welcher Prophet sah das Meer sich teilen, um sein Volk vor dem Pharao zu retten?", ["Musa (Mose)", "Harun (Aaron)", "Yusuf (Josef)", "Isma'il (Ismael)"], "Allah befahl Musa, auf das Meer zu schlagen, und es teilte sich, damit die Gläubigen hindurchziehen konnten."),
"prophets_016": ("Welcher Prophet urteilte gemeinsam mit seinem Vater Dawud über ein von Schafen abgeweidetes Feld?", ["Sulaiman (Salomo)", "Isma'il (Ismael)", "Yusuf (Josef)", "Ishaq (Isaak)"], "Der Koran berichtet, dass Sulaiman und Dawud diesen Fall beurteilten und Allah Sulaiman das Verständnis dafür gab."),
"prophets_017": ("Wessen Mutter wurde angewiesen, ihr Baby in einen Fluss zu legen?", ["Musa (Mose)", "Isa (Jesus)", "Yusuf (Josef)", "Isma'il (Ismael)"], "Allah gab Musas Mutter ein, ihn zum Schutz in einem Kasten auf den Fluss zu setzen."),
"prophets_018": ("Wessen Kamelstute war ein Zeichen für sein Volk, die Thamud?", ["Salih", "Hud", "Shu'ayb", "Lut (Lot)"], "Allah sandte dem Volk der Thamud durch den Propheten Salih eine Kamelstute als Zeichen."),
"prophets_019": ("Welchen Propheten lehrte Allah die Namen aller Dinge?", ["Adam", "Nuh (Noah)", "Ibrahim (Abraham)", "Musa (Mose)"], "Allah lehrte Adam die Namen aller Dinge, und die Engel erkannten Allahs Weisheit an."),
"prophets_020": ("Welcher Prophet sprach als Baby in der Wiege zu den Menschen?", ["Isa (Jesus)", "Yahya (Johannes)", "Yusuf (Josef)", "Ismail (Ismael)"], "Das Baby Isa sprach aus der Wiege: „Ich bin der Diener Allahs; Er hat mir die Schrift gegeben.“"),
"prophets_021": ("Mit welchem Sohn errichtete Ibrahim die Grundmauern der Ka'ba?", ["Ismail (Ismael)", "Ishaq (Isaak)", "Yaqub (Jakob)", "Yusuf (Josef)"], "„Und als Ibrahim und Ismail die Grundmauern des Hauses errichteten…“: Sie bauten gemeinsam."),
"prophets_022": ("Welcher Sohn wurde dem Propheten Zakariyya in seinem Alter angekündigt?", ["Yahya (Johannes)", "Isa (Jesus)", "Ismail (Ismael)", "Ishaq (Isaak)"], "„O Zakariyya, Wir verkünden dir einen Knaben, dessen Name Yahya sein wird.“"),
"prophets_023": ("Was wurde aus Musas Stab, als Allah ihm sagte, ihn zu werfen?", ["Eine sich bewegende Schlange", "Ein Vogel", "Eine Wasserquelle", "Ein Licht"], "„Wirf ihn, o Musa!“ Er warf ihn, und er wurde zu einer Schlange, die sich schnell bewegte."),
"prophets_024": ("Was sah der junge Yusuf in seinem Traum sich vor ihm niederwerfen?", ["Elf Sterne, die Sonne und den Mond", "Sieben fette Kühe", "Einen Goldregen", "Einen Palmengarten"], "Yusuf sah elf Sterne, die Sonne und den Mond sich vor ihm niederwerfen: ein Zeichen seiner Bestimmung."),
"prophets_025": ("Zu welchem Volk wurde der Prophet Hud gesandt?", ["Zu den 'Ad", "Zu den Thamud", "Zum Volk von Madyan", "Zum Volk des Pharao"], "„Und zu den 'Ad ihren Bruder Hud…“: Er rief sie auf, Allah allein anzubeten."),
"prophets_026": ("Zu welchem Volk wurde der Prophet Shu'ayb gesandt?", ["Zum Volk von Madyan", "Zu den 'Ad", "Zu den Thamud", "Zum Volk Nuhs"], "„Und zu Madyan ihren Bruder Shu'ayb…“: Er befahl ihnen, gerechtes Maß und Gewicht zu geben."),
"prophets_027": ("Welcher Prophet wird im Koran „Dhun-Nun“ (der mit dem Fisch) genannt?", ["Yunus (Jona)", "Musa (Mose)", "Sulayman (Salomo)", "Ayyub (Hiob)"], "„Und Dhun-Nun, als er im Zorn davonging…“: Das ist Yunus, der später vom Fisch verschluckt wurde."),
"prophets_028": ("In welcher Sure reist Musa, um von einem Diener zu lernen, dem Allah besonderes Wissen gab?", ["Al-Kahf (Die Höhle)", "Yusuf", "Maryam", "An-Naml"], "In Sure Al-Kahf begleitet Musa einen wissenden Diener und lernt Geduld mit dem, was er noch nicht versteht."),
"prophets_029": ("Welcher Prophet wird im Koran am häufigsten namentlich genannt?", ["Musa (Mose)", "Ibrahim (Abraham)", "Nuh (Noah)", "Isa (Jesus)"], "Musa ist der am häufigsten genannte Prophet im Koran; seine Geschichte mit dem Pharao kehrt oft wieder."),
"prophets_030": ("Wie viele Propheten werden im Koran namentlich erwähnt?", ["25", "10", "50", "99"], "Fünfundzwanzig Propheten werden im Koran genannt, von Adam bis Muhammad ﷺ."),
"prophets_031": ("Welcher Prophet heilte mit Allahs Erlaubnis den Blinden und den Aussätzigen?", ["Isa (Jesus)", "Musa (Mose)", "Dawud (David)", "Yunus (Jona)"], "Isa heilte den Blinden und den Aussätzigen mit Allahs Erlaubnis: ein Zeichen für sein Volk."),
"prophets_032": ("Wie lange blieb Nuh laut Koran bei seinem Volk und rief es zu Allah?", ["950 Jahre", "100 Jahre", "300 Jahre", "40 Jahre"], "„Er blieb unter ihnen tausend Jahre weniger fünfzig“: 950 Jahre geduldigen Rufens."),
"prophets_033": ("Woraus erschuf Allah Adam laut Koran?", ["Aus Lehm", "Aus Licht", "Aus Feuer", "Aus Wasser"], "Allah sagte zu den Engeln: „Ich werde einen Menschen aus Lehm erschaffen.“"),
"prophets_034": ("Wer verführte Adam und seine Frau dazu, vom verbotenen Baum zu essen?", ["Shaytan (Iblis)", "Ein Engel", "Ein Vogel", "Ein König"], "Shaytan flüsterte ihnen ein, von dem Baum zu essen, den Allah verboten hatte."),
"prophets_035": ("Welchen Grund nannte Iblis für seine Weigerung, sich vor Adam niederzuwerfen?", ["„Ich bin besser als er: Du hast mich aus Feuer und ihn aus Lehm erschaffen“", "Er wusste nicht, wer Adam war", "Er fürchtete die Engel", "Er schlief"], "Iblis weigerte sich aus Hochmut: „Du hast mich aus Feuer erschaffen, ihn aber aus Lehm.“"),
"prophets_036": ("Welches Tier sandte Allah nach der Tötung zwischen den beiden Söhnen Adams, um zu zeigen, wie man den Leichnam begräbt?", ["Einen Raben", "Einen Hund", "Eine Taube", "Einen Fuchs"], "Allah sandte einen Raben, der in der Erde scharrte, um dem Mörder zu zeigen, wie er den Leichnam seines Bruders verbergen sollte."),
"prophets_037": ("Was sagt der Koran über den Propheten Idris?", ["Allah erhob ihn an einen hohen Ort", "Er baute eine Arche", "Er wurde von einem Fisch verschluckt", "Er sprach mit den Ameisen"], "„Und Wir erhoben ihn an einen hohen Ort.“"),
"prophets_038": ("Was tat Nuhs Sohn, als sein Vater ihn in die Arche rief?", ["Er weigerte sich und sagte, er werde auf einem Berg Schutz suchen", "Er stieg als Erster ein", "Er baute seine eigene Arche", "Er ging Tiere sammeln"], "Er sagte: „Ich werde auf einem Berg Zuflucht suchen“; die Wellen überwältigten ihn."),
"prophets_039": ("Auf welchem Berg kam Nuhs Arche laut Koran zum Stehen?", ["Auf dem Berg Judi", "Auf dem Berg Sinai", "Auf dem Berg Uhud", "Auf dem Berg Arafat"], "„Und die Arche kam auf dem Judi zum Stehen.“"),
"prophets_040": ("Was befahl Allah Nuh, in die Arche zu laden?", ["Ein Paar von jeder Art und die Gläubigen", "Nur seine Familie", "Nur Vögel", "Gold und Silber"], "„Lade in sie ein Paar von jeder Art und deine Familie… und wer geglaubt hat.“"),
"prophets_041": ("Was taten die Anführer von Nuhs Volk, als sie ihn die Arche bauen sahen?", ["Sie verspotteten ihn", "Sie halfen ihm", "Sie brachten ihm Holz", "Sie beteten mit ihm"], "Sooft Anführer seines Volkes vorbeikamen, verspotteten sie ihn."),
"prophets_042": ("Wie beschreibt der Koran Nuh in der Sure Al-Isra?", ["Als dankbaren Diener", "Als mächtigen König", "Als großen Reisenden", "Als schweigsamen Mann"], "„Wahrlich, er war ein dankbarer Diener.“"),
"prophets_043": ("Wie wurde das Volk der 'Ad vernichtet, zu dem Hud gesandt wurde?", ["Durch einen gewaltigen, tobenden Wind", "Durch eine Flut", "Durch einen Steinregen", "Durch ein Erdbeben"], "„Was die 'Ad betrifft, so wurden sie durch einen eiskalten, tobenden Wind vernichtet.“"),
"prophets_044": ("Was ergriff die Thamud, das Volk Salihs?", ["Ein furchtbarer Schrei", "Eine Flut", "Eine Hungersnot", "Ein Heuschreckenschwarm"], "„Und der Schrei ergriff diejenigen, die Unrecht taten.“"),
"prophets_045": ("Wie heißt der im Koran erwähnte Vater Ibrahims?", ["Azar", "Tarih", "Lut", "Kan'an"], "„Ibrahim sagte zu seinem Vater Azar: Nimmst du Götzen als Götter?“"),
"prophets_046": ("Welchen Götzen ließ Ibrahim nach dem Zerschlagen der Götzen unversehrt?", ["Den größten", "Den kleinsten", "Den goldenen", "Keinen, er zerschlug alle"], "Er zerschlug sie in Stücke, außer dem größten, damit sein Volk ihn befragen würde."),
"prophets_047": ("Was erklärte Ibrahim, nachdem er den Stern, den Mond und dann die Sonne untergehen sah?", ["„Ich liebe nicht, was untergeht“", "„Die Sonne ist mein Herr“", "„Der Mond ist am schönsten“", "„Ich werde schlafen“"], "Als jedes unterging, sagte er: „Ich liebe nicht, was untergeht“, und wandte sich dem Schöpfer zu."),
"prophets_048": ("Wie viele Vögel sollte Ibrahim nehmen, damit Allah ihm zeigte, wie Er die Toten belebt?", ["Vier", "Zwei", "Sieben", "Zwölf"], "„Nimm vier Vögel… dann rufe sie: Sie werden eilends zu dir kommen.“"),
"prophets_049": ("Was setzte Ibrahim seinen Gästen vor, den Engeln, die die frohe Botschaft brachten?", ["Ein gebratenes Kalb", "Datteln", "Milch", "Brot und Honig"], "„Er zögerte nicht, ein gebratenes Kalb zu bringen.“"),
"prophets_050": ("Welche frohe Botschaft brachten die Engel Ibrahims Frau?", ["Die Geburt Ishaqs", "Eine Reise", "Großen Reichtum", "Reichlichen Regen"], "„Wir verkündeten ihr Ishaq und nach Ishaq Ya'qub.“"),
"prophets_051": ("Wie reagierte Ibrahims Sohn, als sein Vater ihm den Traum erzählte, ihn zu opfern?", ["Er nahm es an: „Tu, was dir befohlen wird“", "Er lief davon", "Er weinte und weigerte sich", "Er versteckte sich"], "Er sagte: „O mein Vater, tu, was dir befohlen wird.“ Und Allah löste ihn mit einem großen Opfer aus."),
"prophets_052": ("Wo, sagt Ibrahim in seinem Gebet, hat er einen Teil seiner Familie angesiedelt?", ["In einem Tal ohne Anbau, nahe dem Heiligen Haus", "Am Nil", "In einem Wald", "Auf einer Insel"], "„Ich habe einen Teil meiner Nachkommen in einem unbebauten Tal bei Deinem Heiligen Haus angesiedelt.“"),
"prophets_053": ("Was erbat Ibrahim in seinem Gebet für die Stadt Mekka?", ["Dass sie eine sichere Stadt sei und ihre Bewohner Früchte erhielten", "Dass sie ein Königreich werde", "Dass es dort immer regne", "Dass sie einen Fluss habe"], "„Mein Herr, mache dies zu einer sicheren Stadt und versorge ihre Bewohner mit Früchten.“"),
"prophets_054": ("Beim Errichten der Ka'ba baten Ibrahim und Isma'il Allah, unter ihren Nachkommen zu senden…", ["Einen Gesandten aus ihrer Mitte, der Seine Verse vorträgt", "Einen König", "Ein Heer", "Einen Schatz"], "„Unser Herr, sende unter ihnen einen Gesandten aus ihrer Mitte, der ihnen Deine Verse vorträgt.“"),
"prophets_055": ("Der Koran sagt, ein Prophet war für sich allein „eine Gemeinschaft (Umma)“. Welcher?", ["Ibrahim", "Nuh", "Musa", "Sulayman"], "„Wahrlich, Ibrahim war eine Gemeinschaft, Allah demütig ergeben, aufrichtig.“"),
"prophets_056": ("Für welche Eigenschaft lobt der Koran Isma'il in der Sure Maryam?", ["Er war treu zu seinem Versprechen", "Er war sehr reich", "Er war ein König", "Er konnte schwimmen"], "„Wahrlich, er war treu zu seinem Versprechen, und er war ein Gesandter und ein Prophet.“"),
"prophets_057": ("Welche Strafe traf das Volk Luts?", ["Ein Regen aus Steinen gebrannten Lehms", "Eine Flut", "Ein Insektenschwarm", "Eine Dürre"], "„Wir kehrten die Stadt um und ließen auf sie Steine aus gebranntem Lehm regnen.“"),
"prophets_058": ("Die Frauen welcher beiden Propheten nennt der Koran als Beispiel für Unglauben?", ["Nuh und Lut", "Ibrahim und Musa", "Dawud und Sulayman", "Ayyub und Yunus"], "„Allah führt als Beispiel für die Ungläubigen die Frau Nuhs und die Frau Luts an.“"),
"prophets_059": ("Wer war der Vater Ya'qubs?", ["Ishaq", "Isma'il", "Ibrahim", "Yusuf"], "Die Engel verkündeten Ibrahims Frau „Ishaq und nach Ishaq Ya'qub“."),
"prophets_060": ("Was geschah mit Ya'qubs Augenlicht vom Weinen um Yusuf?", ["Seine Augen wurden weiß", "Er sah nachts besser", "Nichts änderte sich", "Er verlor ein Auge"], "„Seine Augen wurden weiß vor Kummer, und er unterdrückte ihn.“"),
"prophets_061": ("Was gab Ya'qub sein Augenlicht zurück?", ["Yusufs Hemd, über sein Gesicht geworfen", "Eine Pflanze", "Zamzam-Wasser", "Eine Salbe"], "Yusuf sagte: „Werft mein Hemd über das Gesicht meines Vaters; er wird wieder sehen.“"),
"prophets_062": ("Was zog Yusuf vor, statt dem nachzugeben, wozu er zu Unrecht eingeladen wurde?", ["Das Gefängnis", "Das Exil", "Den Reichtum", "Das Schweigen"], "„Mein Herr, das Gefängnis ist mir lieber als das, wozu sie mich einladen.“"),
"prophets_063": ("Im Gefängnis erzählten zwei junge Männer Yusuf ihre Träume. Was sah einer von ihnen?", ["Dass er Trauben presste", "Dass er flog", "Dass er Schafe hütete", "Dass er einen Brunnen grub"], "Einer sah sich Wein pressen, der andere Brot auf dem Kopf tragen, von dem die Vögel fraßen."),
"prophets_064": ("Wie viele Jahre des Überflusses und dann der Dürre sagte Yusuf dem König voraus?", ["Sieben und sieben", "Drei und drei", "Zehn und zehn", "Eins und eins"], "„Ihr werdet sieben Jahre säen… dann werden sieben schwere Jahre kommen.“"),
"prophets_065": ("Um welches Amt bat Yusuf den König von Ägypten?", ["Die Vorratshäuser des Landes", "Den Befehl über das Heer", "Den Thron", "Den Goldschatz"], "„Setze mich über die Vorratshäuser des Landes: Ich bin ein wissender Hüter.“"),
"prophets_066": ("Was ließ Yusuf ins Gepäck seines jüngeren Bruders legen, um ihn bei sich zu behalten?", ["Den Trinkbecher des Königs", "Einen Beutel Gold", "Einen Brief", "Sein Hemd"], "„Er legte den Trinkbecher in den Sack seines Bruders.“"),
"prophets_067": ("Welchen Rat gab Ya'qub seinen Söhnen, bevor sie nach Ägypten zogen?", ["Durch verschiedene Tore einzutreten", "Nachts zu reisen", "Sich zu verkleiden", "Geschenke mitzubringen"], "„Tretet nicht durch ein einziges Tor ein, sondern durch verschiedene Tore.“"),
"prophets_068": ("Warum kamen Yusufs Brüder nach Ägypten, als er dort das Sagen hatte?", ["Um in der Hungersnot Vorräte zu holen", "Um ihn zu finden", "Um zu pilgern", "Um Kamele zu verkaufen"], "Seine Brüder kamen wegen Getreide; sie traten bei ihm ein und erkannten ihn nicht."),
"prophets_069": ("In wessen Haus wurde das Baby Musa aufgenommen, nachdem es in den Fluss gesetzt worden war?", ["Im Haus des Pharao", "Im Haus eines Hirten", "Im Haus eines Fischers", "Im Haus eines Händlers"], "Die Familie des Pharao nahm ihn auf, damit er ihnen eines Tages Feind und Kummer werde."),
"prophets_070": ("Wie kam das Baby Musa schließlich zu seiner Mutter zurück?", ["Er verweigerte jede Amme, und seine Schwester schlug seine Mutter vor", "Der Pharao gab ihn aus Mitleid zurück", "Seine Mutter stahl ihn bei Nacht", "Ein Engel trug ihn"], "Allah ließ ihn die Ammen verweigern; seine Schwester schlug ein Haus vor: Es war das seiner Mutter, die ihn stillte."),
"prophets_071": ("Warum musste Musa Ägypten vor seiner Sendung in Eile verlassen?", ["Er hatte unabsichtlich einen Mann mit einem Schlag getötet", "Er hatte im Palast gestohlen", "Er weigerte sich, Steuern zu zahlen", "Er hatte den Pharao beleidigt"], "Er schlug einen Ägypter, der mit einem Mann seines Volkes kämpfte, und tötete ihn; er bereute es sofort."),
"prophets_072": ("Wer warnte Musa, dass die Anführer planten, ihn zu töten?", ["Ein Mann, der vom anderen Ende der Stadt herbeilief", "Seine Mutter", "Harun", "Ein Soldat"], "„Ein Mann kam vom äußersten Ende der Stadt gelaufen: Sie beraten, dich zu töten, also geh fort!“"),
"prophets_073": ("Was tat Musa bei seiner Ankunft in Madyan für zwei Frauen an der Tränke?", ["Er tränkte ihre Herde", "Er verkaufte ihnen ein Kamel", "Er baute ihnen ein Haus", "Er lehrte sie lesen"], "Er tränkte ihre Herde und zog sich dann in den Schatten zurück, Allah anrufend."),
"prophets_074": ("Wie viele Jahre sollte Musa für den alten Mann von Madyan arbeiten, um dessen Tochter zu heiraten?", ["Acht, und zehn, wenn er wollte", "Eins", "Vierzig", "Drei"], "„Du wirst mir acht Jahre dienen; wenn du zehn vollendest, so ist es dein eigener Wille.“"),
"prophets_075": ("Was befahl Allah Musa im heiligen Tal Tuwa abzulegen?", ["Seine Sandalen", "Seinen Mantel", "Seinen Stab", "Seinen Turban"], "„Zieh deine Sandalen aus: Du bist im heiligen Tal Tuwa.“"),
"prophets_076": ("Was war das zweite Zeichen, das Musa nach dem Stab gegeben wurde?", ["Seine Hand kam weiß hervor, ohne Übel", "Er konnte fliegen", "Seine Stimme wurde zu Donner", "Er sah bei Nacht"], "„Lege deine Hand an deine Seite: Sie wird weiß hervorkommen, ohne Krankheit.“"),
"prophets_077": ("Worum bat Musa Allah, bevor er zum Pharao ging?", ["Ihm die Brust zu weiten und die Zunge zu lösen", "Um ein Heer", "Um Gold", "Um ein schnelles Pferd"], "„Mein Herr, weite mir meine Brust, erleichtere mir meine Aufgabe und löse den Knoten meiner Zunge.“"),
"prophets_078": ("Wen erbat Musa von Allah als Helfer für seine Sendung?", ["Seinen Bruder Harun", "Seinen Sohn", "Seinen Schwiegervater", "Einen Engel"], "„Gib mir einen Helfer aus meiner Familie: Harun, meinen Bruder.“"),
"prophets_079": ("Was taten die Zauberer des Pharao, als Musas Stab ihre Illusionen verschlang?", ["Sie fielen nieder und glaubten", "Sie flohen", "Sie lachten", "Sie griffen Musa an"], "Die Zauberer fielen nieder: „Wir glauben an den Herrn der Welten, den Herrn von Musa und Harun.“"),
"prophets_080": ("Welche dieser Plagen nennt der Koran unter denen, die gegen das Volk des Pharao gesandt wurden?", ["Heuschrecken", "Schnee", "Wölfe", "Feuer"], "„Wir sandten über sie die Flut, die Heuschrecken, die Läuse, die Frösche und das Blut.“"),
"prophets_081": ("Was tat Allah laut Koran mit dem Leichnam des Pharao, nachdem er ertrunken war?", ["Er bewahrte ihn als Zeichen", "Er ließ ihn verschwinden", "Er verbrannte ihn", "Er gab ihn seinem Volk zurück"], "„Heute werden Wir deinen Leib retten, damit du ein Zeichen für die seist, die nach dir kommen.“"),
"prophets_082": ("Worum bat die gläubige Frau des Pharao laut Koran Allah?", ["Um ein Haus bei Ihm im Paradies", "Um einen Sohn", "Um den Tod des Pharao", "Um ein Königreich"], "„Mein Herr, baue mir bei Dir ein Haus im Paradies und rette mich vor dem Pharao.“"),
"prophets_083": ("Wie viele Nächte dauerte Allahs Verabredung mit Musa auf dem Berg?", ["Vierzig", "Sieben", "Zehn", "Hundert"], "„Wir bestimmten Musa dreißig Nächte und vervollständigten sie mit zehn: vierzig Nächte.“"),
"prophets_084": ("Was geschah, als Musa darum bat, Allah zu sehen?", ["Allah offenbarte Sich dem Berg, der zerfiel, und Musa fiel ohnmächtig nieder", "Er sah Allah", "Nichts geschah", "Der Berg stieg in den Himmel"], "„Schau auf den Berg: Wenn er an seinem Platz bleibt, wirst du Mich sehen.“ Der Berg wurde zermalmt, und Musa fiel ohnmächtig nieder."),
"prophets_085": ("Worauf schrieb Allah Ermahnungen und Erklärungen für Musa?", ["Auf Tafeln", "Auf Palmblätter", "Auf einen schwarzen Stein", "Auf Leder"], "„Wir schrieben ihm auf die Tafeln eine Ermahnung über alle Dinge.“"),
"prophets_086": ("Wer machte das Kalb, das die Kinder Israels in Musas Abwesenheit anbeteten?", ["As-Samiri", "Harun", "Der Pharao", "Qarun"], "„As-Samiri hat sie in die Irre geführt“: Aus ihrem Schmuck machte er ein Kalb, das einen brüllenden Laut gab."),
"prophets_087": ("Wie viele Quellen sprudelten aus dem Felsen, auf den Musa mit seinem Stab schlug?", ["Zwölf", "Sieben", "Drei", "Vierzig"], "„Schlag mit deinem Stab auf den Felsen“: Zwölf Quellen sprudelten hervor, eine für jeden Stamm."),
"prophets_088": ("Welche Speise sandte Allah den Kindern Israels in der Wüste herab?", ["Manna und Wachteln", "Reis und Fisch", "Datteln und Milch", "Brot und Oliven"], "„Wir sandten auf euch Manna und Wachteln herab.“"),
"prophets_089": ("Welche Farbe hatte die Kuh, die Musa den Kindern Israels zu opfern befahl?", ["Leuchtend gelb", "Schwarz", "Weiß", "Rot"], "„Es ist eine gelbe Kuh, von leuchtender Farbe, die die Betrachter erfreut.“"),
"prophets_090": ("Wer aus Musas Volk wurde wegen seines Hochmuts und Reichtums mitsamt seinem Haus von der Erde verschlungen?", ["Qarun", "Haman", "As-Samiri", "Jalut"], "Qarun besaß riesige Schätze; „Wir ließen die Erde ihn und sein Haus verschlingen“."),
"prophets_091": ("Welches Metall machte Allah für Dawud weich?", ["Eisen", "Gold", "Kupfer", "Silber"], "„Und Wir machten ihm das Eisen geschmeidig.“"),
"prophets_092": ("Was lehrte Allah Dawud herzustellen, um die Menschen im Kampf zu schützen?", ["Kettenpanzer", "Schwerter", "Holzschilde", "Türme"], "„Wir lehrten ihn die Herstellung von Panzerhemden, um euch zu schützen.“"),
"prophets_093": ("Welchen Riesen tötete Dawud laut Koran in der Schlacht?", ["Jalut (Goliath)", "Den Pharao", "Haman", "Nimrod"], "„Und Dawud tötete Jalut, und Allah gab ihm die Herrschaft und die Weisheit.“"),
"prophets_094": ("Wie prüfte König Talut sein Heer, bevor es Jalut gegenübertrat?", ["Mit einem Fluss: nicht daraus zu trinken, außer eine Handvoll", "Mit einem Wettlauf", "Mit einem dreitägigen Fasten", "Mit einem zu besteigenden Berg"], "„Allah wird euch mit einem Fluss prüfen: Wer daraus trinkt, gehört nicht zu mir, außer wer eine Handvoll schöpft.“"),
"prophets_095": ("Was ließ Allah gemeinsam mit Dawud Ihn lobpreisen?", ["Die Berge und die Vögel", "Die Winde", "Die Dschinn", "Die Fische"], "„Und Wir machten die Berge dienstbar, dass sie mit Dawud Uns preisen, und die Vögel.“"),
"prophets_096": ("Welches Element machte Allah Sulayman dienstbar, um ihn zu tragen, wohin er wollte?", ["Den Wind", "Das Feuer", "Den Regen", "Das Meer"], "„Und Sulayman den Wind, der auf seinen Befehl kräftig zum gesegneten Land wehte.“"),
"prophets_097": ("Welcher Vogel brachte Sulayman Nachricht vom Königreich Saba?", ["Der Wiedehopf", "Der Adler", "Die Taube", "Der Rabe"], "Der Wiedehopf kehrte zurück und sagte: „Ich habe etwas erfahren, was du nicht weißt, und ich bringe dir aus Saba sichere Kunde.“"),
"prophets_098": ("Welches kleine Geschöpf warnte die Seinen, sich hineinzubegeben, als Sulaymans Heer nahte?", ["Eine Ameise", "Eine Biene", "Eine Maus", "Eine Spinne"], "Eine Ameise sagte: „O ihr Ameisen, geht in eure Wohnungen, damit Sulayman und seine Heerscharen euch nicht unbemerkt zertreten!“"),
"prophets_099": ("Wie schnell wurde der Thron der Königin von Saba zu Sulayman gebracht?", ["Bevor sein Blick zu ihm zurückkehrte", "In einem Tag", "In sieben Tagen", "In einem Monat"], "Derjenige, der Wissen aus dem Buch hatte, sagte: „Ich bringe ihn dir, bevor dein Blick zu dir zurückkehrt.“"),
"prophets_100": ("Was fertigten die Dschinn laut Koran für Sulayman?", ["Heiligtümer, Statuen und große Becken", "Fliegende Teppiche", "Schiffe", "Berge"], "„Sie machten ihm, was er wollte: Hallen, Statuen, Becken wie Wasserbehälter und fest stehende Kessel.“"),
"prophets_101": ("Wie erfuhren die Dschinn von Sulaymans Tod?", ["Ein Erdgeschöpf nagte an seinem Stab, und er fiel", "Ein Engel sagte es ihnen", "Der Wiedehopf sagte es ihnen", "Sie sahen ihn sterben"], "Erst das „Erdgeschöpf“, das seinen Stab fraß, offenbarte seinen Tod; die Dschinn erkannten, dass sie das Verborgene nicht kannten."),
"prophets_102": ("Welches besondere Gebet richtete Sulayman an Allah?", ["Um ein Reich, das niemand nach ihm haben würde", "Um ein langes Leben", "Um den Reichtum Qaruns", "Um die Fähigkeit zu fliegen"], "„Mein Herr, vergib mir und schenke mir ein Reich, wie es niemandem nach mir zusteht.“"),
"prophets_103": ("Was befahl Allah Ayyub, um seine Gesundheit wiederzuerlangen?", ["Mit dem Fuß auf den Boden zu stampfen: Eine kühle Quelle sprudelte hervor", "Einen Monat zu fasten", "Im Meer zu baden", "Einen Berg zu besteigen"], "„Stampfe mit deinem Fuß: Hier ist eine kühle Quelle zum Waschen und Trinken.“"),
"prophets_104": ("Welches Bittgebet sprach Yunus in der Dunkelheit des Fischbauchs?", ["„Es gibt keinen Gott außer Dir! Gepriesen seist Du, ich war einer der Ungerechten“", "„Mein Herr, gib mir ein Reich“", "„Mein Herr, sende mir Regen“", "„Mein Herr, lass mich Dich sehen“"], "„Er rief in der Finsternis: Es gibt keinen Gott außer Dir! Gepriesen seist Du; ich war einer der Ungerechten.“"),
"prophets_105": ("Welche Pflanze ließ Allah über Yunus wachsen, nachdem der Fisch ihn ausgespien hatte?", ["Eine Kürbispflanze (Yaqtin)", "Eine Palme", "Einen Olivenbaum", "Einen Weinstock"], "„Und Wir ließen über ihm eine Kürbispflanze wachsen.“"),
"prophets_106": ("Zu wie vielen Menschen wurde Yunus laut Koran gesandt?", ["Zu hunderttausend oder mehr", "Zu tausend", "Zu zehntausend", "Zu zwölf"], "„Und Wir sandten ihn zu hunderttausend oder mehr.“"),
"prophets_107": ("Welches Zeichen gab Allah Zakariyya, um die Ankunft seines Sohnes zu bestätigen?", ["Drei Nächte lang nicht zu den Menschen zu sprechen, obwohl gesund", "Eine Sternschnuppe", "Regen im Sommer", "Einen Traum"], "„Dein Zeichen ist, dass du drei Nächte lang nicht zu den Menschen sprechen wirst, obwohl gesund.“"),
"prophets_108": ("Was sagt Allah über den Namen Yahya?", ["Niemand vor ihm hatte diesen Namen erhalten", "Es war der Name seines Großvaters", "Seine Mutter wählte ihn", "Es war ein Königsname"], "„Wir verkünden dir einen Knaben, dessen Name Yahya sein wird; Wir haben diesen Namen zuvor niemandem gegeben.“"),
"prophets_109": ("Was gewährte Allah Yahya, als er noch ein Kind war?", ["Die Weisheit", "Ein Königreich", "Ein Pferd", "Einen Schatz"], "„O Yahya, nimm die Schrift mit Entschlossenheit.“ Und Wir gaben ihm das Urteil, als er noch ein Knabe war."),
"prophets_110": ("Was hatte Maryams Mutter für das Kind gelobt, das sie trug?", ["Es dem Dienst Allahs zu weihen", "Es nach Ägypten zu schicken", "Es zum König zu machen", "Es einem Hirten anzuvertrauen"], "„Mein Herr, ich habe Dir gelobt, was in meinem Leib ist, Deinem Dienst geweiht.“"),
"prophets_111": ("Welcher Prophet übernahm nach ihrer Geburt die Sorge für Maryam?", ["Zakariyya", "Yahya", "Isa", "Dawud"], "„Und Er gab sie in die Obhut Zakariyyas“, der bei ihr Versorgung von Allah fand."),
"prophets_112": ("Über wen erwählte Allah Maryam laut Koran?", ["Über die Frauen der Welten", "Über die Königinnen", "Über die Engel", "Über die Propheten"], "„O Maryam, Allah hat dich erwählt und gereinigt und dich über die Frauen der Welten erwählt.“"),
"prophets_113": ("Was fiel für Maryam herab, als sie den Stamm der Palme schüttelte?", ["Frische, reife Datteln", "Oliven", "Feigen", "Regen"], "„Schüttle den Stamm der Palme zu dir: Sie wird frische, reife Datteln auf dich fallen lassen.“"),
"prophets_114": ("Welches Wort verwendet der Koran für Maryam in der Sure Al-Ma'ida?", ["Wahrhaftig (Siddiqa)", "Königin", "Prophetin", "Kriegerin"], "„Der Messias, Sohn Maryams, war nur ein Gesandter… und seine Mutter war eine Wahrhaftige.“"),
"prophets_115": ("Welchen Titel gibt der Koran Isa, dem Sohn Maryams?", ["Al-Masih (der Messias)", "Al-Khalil", "Al-Kalim", "As-Siddiq"], "„Sein Name wird der Messias sein, Isa, Sohn Maryams, angesehen im Diesseits und im Jenseits.“"),
"prophets_116": ("Was formte Isa mit Allahs Erlaubnis aus Lehm?", ["Die Gestalt eines Vogels, der lebendig wurde", "Ein Haus", "Die Statue eines Königs", "Ein Boot"], "„Ich forme euch aus Lehm die Gestalt eines Vogels, dann hauche ich ihm ein, und er wird mit Allahs Erlaubnis ein Vogel.“"),
"prophets_117": ("Wie heißen Isas enge Gefährten, die sich zu „Helfern Allahs“ erklärten?", ["Die Hawariyyun (Jünger)", "Die Ansar", "Die Muhajirun", "Die Sahaba"], "„Die Jünger sagten: Wir sind die Helfer Allahs.“"),
"prophets_118": ("Worum baten die Jünger Isa, was der Sure Al-Ma'ida ihren Namen gab?", ["Um einen gedeckten Tisch, vom Himmel herabgesandt", "Um ein Buch", "Um ein Königreich", "Um Gold"], "„Kann dein Herr uns einen gedeckten Tisch vom Himmel herabsenden?“"),
"prophets_119": ("Was sagt der Koran über das Ende von Isas Sendung auf Erden?", ["Er wurde weder getötet noch gekreuzigt: Allah erhob ihn zu Sich", "Er starb an Altersschwäche", "Er ertrank", "Er ging nach Ägypten"], "„Sie töteten ihn nicht und kreuzigten ihn nicht… vielmehr erhob Allah ihn zu Sich.“"),
"prophets_120": ("Unter welchem Namen kündigte Isa einen Gesandten an, der nach ihm kommen würde?", ["Ahmad", "Yahya", "Musa", "Ilyas"], "„…als Verkünder eines Gesandten, der nach mir kommt, dessen Name Ahmad ist.“"),
"prophets_121": ("Welchen Götzen warf der Prophet Ilyas seinem Volk vor anzubeten?", ["Ba'l", "Hubal", "Al-Lat", "Wadd"], "„Ruft ihr Ba'l an und verlasst den besten der Schöpfer?“"),
"prophets_122": ("Welche drei Propheten nennt der Koran gemeinsam „unter den Geduldigen“?", ["Isma'il, Idris und Dhul-Kifl", "Nuh, Hud und Salih", "Musa, Harun und Yusha'", "Dawud, Sulayman und Ayyub"], "„Und Isma'il, Idris und Dhul-Kifl: Alle gehörten zu den Geduldigen.“"),
"prophets_123": ("Welcher Prophet wird in der Sure Sad neben Isma'il und Dhul-Kifl genannt?", ["Al-Yasa' (Elisa)", "Yunus", "Lut", "Shu'ayb"], "„Und gedenke Isma'ils, Al-Yasa's und Dhul-Kifls: Alle gehören zu den Besten.“"),
"prophets_124": ("Welchen Titel gibt der Koran dem Propheten Muhammad ﷺ in Vers 33:40?", ["Das Siegel der Propheten", "Der König der Araber", "Der Vater der Gläubigen", "Der Freund Allahs"], "„Muhammad… ist der Gesandte Allahs und das Siegel der Propheten.“"),
"prophets_125": ("Als was wurde der Prophet Muhammad ﷺ laut Koran gesandt?", ["Als Barmherzigkeit für die Welten", "Als König", "Als Richter", "Als Krieger"], "„Wir haben dich nur als Barmherzigkeit für die Welten gesandt.“"),
"prophets_126": ("Was tun Allah und Seine Engel laut Vers 33:56 für den Propheten ﷺ?", ["Sie sprechen den Segen über ihn", "Sie schützen ihn vor Winden", "Sie senden ihm Regen", "Sie beobachten ihn schweigend"], "„Allah und Seine Engel sprechen den Segen über den Propheten. O ihr Gläubigen, sprecht den Segen über ihn und grüßt ihn mit Frieden!“"),
"prophets_127": ("Wie beschreibt der Koran den Charakter des Propheten ﷺ in der Sure Al-Qalam?", ["„Du bist von gewaltigem Charakter“", "„Du bist ein großer König“", "„Du bist der Reichste“", "„Du bist der Stärkste“"], "„Und wahrlich, du bist von gewaltigem Charakter.“"),
"prophets_128": ("Woran erinnert Vers 3:144 in Bezug auf Muhammad ﷺ?", ["Er ist nur ein Gesandter, und vor ihm sind schon Gesandte dahingegangen", "Er wird nie sterben", "Er ist ein Engel", "Er kennt die Zukunft"], "„Muhammad ist nur ein Gesandter; vor ihm sind schon Gesandte dahingegangen.“"),
"prophets_129": ("Welche fünf Propheten nennt Vers 33:7 gemeinsam für den feierlichen Bund?", ["Nuh, Ibrahim, Musa, Isa und Muhammad ﷺ", "Adam, Nuh, Hud, Salih und Lut", "Dawud, Sulayman, Ayyub, Yunus und Idris", "Isma'il, Ishaq, Ya'qub, Yusuf und Musa"], "„Wir nahmen von den Propheten ihren Bund: von dir, von Nuh, Ibrahim, Musa und Isa, dem Sohn Maryams.“"),
"prophets_130": ("Welche Arbeit verrichtete laut einem Hadith bei al-Buchari jeder Prophet?", ["Hirte", "Zimmermann", "Schmied", "Händler"], "„Allah sandte keinen Propheten, der nicht Schafe gehütet hätte“, und der Prophet ﷺ hütete sie für die Leute von Mekka."),
"prophets_131": ("Welcher Prophet arbeitete laut einem Hadith bei Muslim als Zimmermann?", ["Zakariyya", "Nuh", "Idris", "Yusuf"], "Der Prophet ﷺ sagte: „Zakariyya war ein Zimmermann.“"),
"prophets_132": ("Von welchem Propheten sagte der Prophet ﷺ, er stehe ihm „von allen Menschen am nächsten“, in dieser Welt und der nächsten?", ["Isa, Sohn Maryams", "Musa", "Ibrahim", "Nuh"], "„Ich stehe von allen Menschen Isa, dem Sohn Maryams, am nächsten in dieser Welt und im Jenseits; die Propheten sind Brüder.“"),
"prophets_133": ("Wie viele Suren des Korans sind nach einem Propheten benannt?", ["Sechs", "Zwei", "Zwölf", "Fünfundzwanzig"], "Yunus (10), Hud (11), Yusuf (12), Ibrahim (14), Muhammad (47) und Nuh (71)."),
"prophets_134": ("Mit welchen drei Worten beschreibt der Koran Ibrahim in Vers 11:75?", ["Nachsichtig, weichherzig, sich stets Allah zuwendend", "Reich, mächtig, gelehrt", "Stark, schnell, tapfer", "König, Richter, Krieger"], "„Wahrlich, Ibrahim war nachsichtig, weichherzig und wandte sich stets Allah zu.“"),
"prophets_135": ("Was warf Shu'ayb seinem Volk außer dem Götzendienst vor?", ["Betrug bei Gewicht und Maß", "Nicht zu beten", "Nachts zu reisen", "Fisch zu essen"], "„Gebt volles Maß und Gewicht, und enthaltet den Menschen nicht vor, was ihnen zusteht.“"),
"prophets_136": ("Was ergriff Shu'aybs Volk, nachdem es seine Botschaft abgelehnt hatte?", ["Ein Erdbeben", "Eine Flut", "Ein Feuerregen", "Ein Vogelschwarm"], "„Da ergriff sie das Erdbeben, und am Morgen lagen sie in ihren Häusern leblos auf dem Boden.“"),
"prophets_137": ("Welche Nachricht gaben die Engel Ibrahim, nachdem sie seine Furcht beruhigt hatten?", ["Dass sie zum Volk Luts gesandt seien", "Dass eine Flut komme", "Dass die Ka'ba zerstört werde", "Dass der Pharao ertrinken werde"], "„Fürchte dich nicht: Wir sind zum Volk Luts gesandt.“"),
"prophets_138": ("Was erbat Ibrahim in Vers 14:40 für sich und seine Nachkommen?", ["Zu denen zu gehören, die das Gebet verrichten", "Könige zu sein", "Reich zu sein", "Lange zu leben"], "„Mein Herr, mache mich zu einem, der das Gebet verrichtet, und auch meine Nachkommen.“"),
"prophets_139": ("Wen erhob Yusuf am Ende seiner Geschichte auf den Thron, bevor sich alle vor ihm niederwarfen?", ["Seine Eltern", "Den König", "Seine Brüder", "Seinen Sohn"], "„Er erhob seine Eltern auf den Thron, und sie fielen vor ihm nieder“: Der Kindheitstraum erfüllte sich."),
"prophets_140": ("Warum wollten Yusufs Brüder ihn loswerden?", ["Aus Eifersucht: Ihr Vater liebte ihn mehr", "Er hatte gestohlen", "Er weigerte sich zu arbeiten", "Er war krank"], "„Yusuf und sein Bruder sind unserem Vater lieber als wir… Tötet Yusuf oder verstoßt ihn in ein Land.“"),
"prophets_141": ("Was brachten Yusufs Brüder ihrem Vater, damit er glaubte, ein Wolf habe ihn gefressen?", ["Sein Hemd mit falschem Blut befleckt", "Seine Sandalen", "Seinen Stab", "Den Zahn eines Wolfes"], "„Sie brachten sein Hemd mit falschem Blut“; Ya'qub antwortete: „Schöne Geduld.“"),
"prophets_142": ("Was versprach Allah Musas Mutter, als Er ihr eingab, ihn in den Fluss zu legen?", ["Ihn ihr zurückzugeben und zum Gesandten zu machen", "Ihr einen anderen Sohn zu geben", "Sie zur Königin zu machen", "Regen zu senden"], "„Fürchte dich nicht und sei nicht traurig: Wir werden ihn dir zurückgeben und ihn zu einem der Gesandten machen.“"),
"prophets_143": ("Womit schlug Musa auf das Meer, damit es sich teilte?", ["Mit seinem Stab", "Mit seiner Hand", "Mit einem Stein", "Mit seinem Schwert"], "„Schlag mit deinem Stab auf das Meer“: Es teilte sich, und jede Seite war wie ein gewaltiger Berg."),
"prophets_144": ("Was war das Erste, was Allah zu Musa sagte, als Er ihn ansprach?", ["„Ich bin Allah, es gibt keinen Gott außer Mir: Diene Mir und verrichte das Gebet“", "„Geh fischen“", "„Baue eine Arche“", "„Geh zurück zum Pharao“"], "„Wahrlich, Ich bin Allah; es gibt keinen Gott außer Mir, so diene Mir und verrichte das Gebet zu Meinem Gedenken.“"),
"prophets_145": ("Wie sollten Musa und Harun laut Allah mit dem Pharao sprechen?", ["Mit sanften Worten", "Mit Zorn", "Schreiend", "Schweigend"], "„Geht zum Pharao… und sprecht mit ihm sanfte Worte; vielleicht lässt er sich ermahnen oder fürchtet sich.“"),
"prophets_146": ("Was sagte Musa zu seinem jungen Diener zu Beginn seiner Reise zum Zusammenfluss der beiden Meere?", ["Dass er nicht aufhören werde, bis er den Zusammenfluss der beiden Meere erreiche", "Dass er nach Hause wolle", "Dass er Angst habe", "Dass er Gold suche"], "„Ich werde nicht aufgeben, bis ich den Zusammenfluss der beiden Meere erreiche, auch wenn ich lange Zeit weitergehen muss.“"),
"prophets_147": ("Was tat der wissende Diener vor Musa, der es im Moment nicht verstand?", ["Er schlug ein Loch in ein Boot", "Er baute eine Brücke", "Er zündete ein Feuer an", "Er pflanzte einen Baum"], "Er durchlöcherte das Boot, tötete dann einen Jungen und richtete eine Mauer auf, und erklärte Musa danach jede Tat."),
"prophets_148": ("Was waren Isas erste Worte, noch in der Wiege?", ["„Ich bin der Diener Allahs; Er gab mir die Schrift und machte mich zum Propheten“", "„Ich bin der Sohn Gottes“", "„Ich bin ein König“", "„Ich habe Hunger“"], "„Er sagte: Ich bin der Diener Allahs. Er hat mir die Schrift gegeben und mich zum Propheten gemacht.“"),
"prophets_149": ("Was sagten Adam und seine Frau zu Allah, nachdem sie vom Baum gegessen hatten?", ["„Unser Herr, wir haben uns selbst Unrecht getan; wenn Du uns nicht vergibst, sind wir verloren“", "„Es war nicht unsere Schuld“", "„Der Baum war schuld“", "Sie sagten nichts"], "„Unser Herr, wir haben uns selbst Unrecht getan, und wenn Du uns nicht vergibst und Dich unser erbarmst, gehören wir gewiss zu den Verlierern.“"),
"prophets_150": ("Welchen Auftrag gab Allah Nuh gegenüber seinem Volk, im ersten Vers der Sure Nuh?", ["Sie zu warnen, bevor eine schmerzhafte Strafe über sie kommt", "Eine Stadt zu bauen", "Ihnen das Fischen beizubringen", "Sie zu Königen zu machen"], "„Wir sandten Nuh zu seinem Volk: Warne dein Volk, bevor eine schmerzhafte Strafe über sie kommt.“"),
}
